<?php

/**
 * Sorts an associative array of arrays based on the 'age' field.
 *
 * @param array $set An associative array where each entry contains at least three fields:
 *                   - name (string)
 *                   - address (string)
 *                   - age (integer)
 * @param string $order A string indicating the order: either 'asc' or 'desc'.
 *
 * @return array The sorted array.
 */
function smart_sort_array($set, $order = 'asc') {
    usort($set, function ($a, $b) use ($order) {
        if ($a['age'] == $b['age']) return 0;
        return ($order === 'asc') ? ($a['age'] < $b['age']) : ($a['age'] > $b['age']);
    });

    return $set;
}

// Example usage
$people = [
    ['name' => 'John', 'address' => '123 Elm St', 'age' => 30],
    ['name' => 'Jane', 'address' => '456 Oak Dr', 'age' => 28],
    ['name' => 'Doe', 'address' => '789 Maple Ln', 'age' => 35]
];

echo "Before sorting:\n";
print_r($people);

$sorted_people_asc = smart_sort_array($people);
echo "\nAfter ascending sort:\n";
print_r($sorted_people_asc);

$sorted_people_desc = smart_sort_array($people, 'desc');
echo "\nAfter descending sort:\n";
print_r($sorted_people_desc);

?>
```

